import { DatabaseSync } from "node:sqlite";
import fs from "node:fs";
import path from "node:path";

const DB_PATH = "/home/user/qwik-app/db.sqlite";

// A module-level singleton so we don't re-open / re-seed the database on
// every request (Vite/Qwik will keep this module alive for the life of the
// server process in dev & production).
let dbInstance: DatabaseSync | null = null;

function createSchema(db: DatabaseSync) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS Product (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      price REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS Coupon (
      code TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      value REAL NOT NULL,
      minSpend REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS CartItem (
      productId INTEGER PRIMARY KEY,
      quantity INTEGER NOT NULL,
      FOREIGN KEY(productId) REFERENCES Product(id)
    );

    CREATE TABLE IF NOT EXISTS ActiveCoupon (
      code TEXT PRIMARY KEY,
      FOREIGN KEY(code) REFERENCES Coupon(code)
    );
  `);
}

function seedIfEmpty(db: DatabaseSync) {
  const productCount = db
    .prepare("SELECT COUNT(*) AS c FROM Product")
    .get() as { c: number };

  if (productCount.c === 0) {
    const insertProduct = db.prepare(
      "INSERT INTO Product (name, price) VALUES (?, ?)",
    );
    insertProduct.run("Widget", 25.0);
    insertProduct.run("Gadget", 50.0);
    insertProduct.run("Gizmo", 15.0);
    insertProduct.run("Doohickey", 10.0);
  }

  const couponCount = db
    .prepare("SELECT COUNT(*) AS c FROM Coupon")
    .get() as { c: number };

  if (couponCount.c === 0) {
    const insertCoupon = db.prepare(
      "INSERT INTO Coupon (code, type, value, minSpend) VALUES (?, ?, ?, ?)",
    );
    // 15% off when spending at least $50
    insertCoupon.run("SAVE15", "PERCENT", 15.0, 50.0);
    // $10 flat off when spending at least $20
    insertCoupon.run("FLAT10", "FIXED", 10.0, 20.0);
    // Buy One Get One Free on product id 3 (Gizmo), no minimum spend
    insertCoupon.run("BOGOGIZMO", "BOGO", 3.0, 0.0);
  }
}

export function getDb(): DatabaseSync {
  if (dbInstance) {
    return dbInstance;
  }

  const dir = path.dirname(DB_PATH);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const db = new DatabaseSync(DB_PATH);
  db.exec("PRAGMA foreign_keys = ON;");

  createSchema(db);
  seedIfEmpty(db);

  dbInstance = db;
  return dbInstance;
}

import { getDb } from "./db";

export type CouponType = "PERCENT" | "FIXED" | "BOGO";

export interface CouponRow {
  code: string;
  type: CouponType;
  value: number;
  minSpend: number;
}

export interface CartItemView {
  productId: number;
  name: string;
  price: number;
  quantity: number;
  total: number;
}

export interface CartState {
  items: CartItemView[];
  subtotal: number;
  coupon: CouponRow | null;
  discount: number;
  total: number;
  error: string | null;
}

/** Round to 2 decimal places, avoiding floating point artifacts. */
function round2(n: number): number {
  return Math.round((n + Number.EPSILON) * 100) / 100;
}

function getCartItemsWithProducts(): CartItemView[] {
  const db = getDb();
  const rows = db
    .prepare(
      `SELECT CartItem.productId AS productId,
              Product.name AS name,
              Product.price AS price,
              CartItem.quantity AS quantity
         FROM CartItem
         JOIN Product ON Product.id = CartItem.productId
        ORDER BY CartItem.productId ASC`,
    )
    .all() as {
    productId: number;
    name: string;
    price: number;
    quantity: number;
  }[];

  return rows.map((row) => ({
    productId: row.productId,
    name: row.name,
    price: row.price,
    quantity: row.quantity,
    total: round2(row.price * row.quantity),
  }));
}

function getActiveCoupon(): CouponRow | null {
  const db = getDb();
  const row = db
    .prepare(
      `SELECT Coupon.code AS code,
              Coupon.type AS type,
              Coupon.value AS value,
              Coupon.minSpend AS minSpend
         FROM ActiveCoupon
         JOIN Coupon ON Coupon.code = ActiveCoupon.code
        LIMIT 1`,
    )
    .get() as CouponRow | undefined;

  return row ?? null;
}

function removeActiveCoupon(): void {
  const db = getDb();
  db.prepare("DELETE FROM ActiveCoupon").run();
}

function getProductPrice(productId: number): number | null {
  const db = getDb();
  const row = db
    .prepare("SELECT price FROM Product WHERE id = ?")
    .get(productId) as { price: number } | undefined;
  return row ? row.price : null;
}

/**
 * Computes the discount (in dollars) for a given coupon against the
 * provided cart items / subtotal. Does not perform any minSpend validation.
 */
function computeRawDiscount(
  coupon: CouponRow,
  subtotal: number,
  items: CartItemView[],
): number {
  switch (coupon.type) {
    case "PERCENT": {
      return subtotal * (coupon.value / 100);
    }
    case "FIXED": {
      return coupon.value;
    }
    case "BOGO": {
      const bogoProductId = Math.trunc(coupon.value);
      const item = items.find((i) => i.productId === bogoProductId);
      if (!item) {
        return 0;
      }
      const freeUnits = Math.floor(item.quantity / 2);
      const unitPrice = item.price;
      return freeUnits * unitPrice;
    }
    default:
      return 0;
  }
}

/**
 * Builds the full, authoritative cart state from the database. This is the
 * single source of truth used by both the GET/POST `/api/cart` endpoint and
 * the `/cart` UI route. All discount math & coupon validation happens here,
 * server-side, on every call.
 */
export function getCartState(): CartState {
  const items = getCartItemsWithProducts();
  const subtotal = round2(
    items.reduce((sum, item) => sum + item.price * item.quantity, 0),
  );

  let coupon = getActiveCoupon();
  let discount = 0;
  let error: string | null = null;

  if (coupon) {
    if (subtotal < coupon.minSpend) {
      // The cart changed (or the coupon was applied) in a way that no
      // longer satisfies the coupon's minimum spend requirement. Invalidate
      // it in the database and surface the error to the caller.
      removeActiveCoupon();
      coupon = null;
      discount = 0;
      error = "Minimum spend not met";
    } else {
      const rawDiscount = computeRawDiscount(coupon, subtotal, items);
      const cappedTotal = Math.max(subtotal - rawDiscount, 0);
      discount = round2(subtotal - cappedTotal);
    }
  }

  const total = round2(Math.max(subtotal - discount, 0));

  return {
    items,
    subtotal,
    coupon,
    discount,
    total,
    error,
  };
}

export function updateCartItemQuantity(
  productId: number,
  quantity: number,
): CartState {
  const db = getDb();

  if (quantity <= 0) {
    db.prepare("DELETE FROM CartItem WHERE productId = ?").run(productId);
  } else {
    // Ensure the product exists before inserting a cart row for it.
    const price = getProductPrice(productId);
    if (price === null) {
      return { ...getCartState(), error: "Invalid product" };
    }

    db.prepare(
      `INSERT INTO CartItem (productId, quantity) VALUES (?, ?)
       ON CONFLICT(productId) DO UPDATE SET quantity = excluded.quantity`,
    ).run(productId, quantity);
  }

  return getCartState();
}

export function applyCoupon(code: string): CartState {
  const db = getDb();

  const coupon = db
    .prepare(
      "SELECT code, type, value, minSpend FROM Coupon WHERE code = ?",
    )
    .get(code) as CouponRow | undefined;

  if (!coupon) {
    return { ...getCartState(), error: "Invalid coupon code" };
  }

  const items = getCartItemsWithProducts();
  const subtotal = round2(
    items.reduce((sum, item) => sum + item.price * item.quantity, 0),
  );

  if (subtotal < coupon.minSpend) {
    return { ...getCartState(), error: "Minimum spend not met" };
  }

  db.prepare("DELETE FROM ActiveCoupon").run();
  db.prepare("INSERT INTO ActiveCoupon (code) VALUES (?)").run(coupon.code);

  return getCartState();
}

export function clearCart(): CartState {
  const db = getDb();
  db.prepare("DELETE FROM CartItem").run();
  db.prepare("DELETE FROM ActiveCoupon").run();
  return getCartState();
}

export function listProducts(): { id: number; name: string; price: number }[] {
  const db = getDb();
  return db
    .prepare("SELECT id, name, price FROM Product ORDER BY id ASC")
    .all() as { id: number; name: string; price: number }[];
}

import type { RequestHandler } from "@builder.io/qwik-city";
import {
  applyCoupon,
  clearCart,
  getCartState,
  updateCartItemQuantity,
} from "~/lib/cart";

type CartAction =
  | { action: "update"; productId: number; quantity: number }
  | { action: "applyCoupon"; code: string }
  | { action: "clear" };

export const onGet: RequestHandler = async (requestEvent) => {
  const state = getCartState();
  requestEvent.json(200, state);
};

export const onPost: RequestHandler = async (requestEvent) => {
  let body: unknown;
  try {
    body = await requestEvent.parseBody();
  } catch {
    body = null;
  }

  if (!body || typeof body !== "object") {
    requestEvent.json(400, {
      ...getCartState(),
      error: "Invalid request body",
    });
    return;
  }

  const payload = body as Partial<CartAction> & Record<string, unknown>;

  switch (payload.action) {
    case "update": {
      const productId = Number((payload as any).productId);
      const quantity = Number((payload as any).quantity);
      if (!Number.isFinite(productId) || !Number.isFinite(quantity)) {
        requestEvent.json(400, {
          ...getCartState(),
          error: "Invalid product or quantity",
        });
        return;
      }
      const state = updateCartItemQuantity(productId, quantity);
      requestEvent.json(200, state);
      return;
    }

    case "applyCoupon": {
      const code = String((payload as any).code ?? "");
      const state = applyCoupon(code);
      requestEvent.json(200, state);
      return;
    }

    case "clear": {
      const state = clearCart();
      requestEvent.json(200, state);
      return;
    }

    default: {
      requestEvent.json(400, {
        ...getCartState(),
        error: "Unknown action",
      });
      return;
    }
  }
};

import { component$ } from "@builder.io/qwik";
import {
  routeAction$,
  routeLoader$,
  z,
  zod$,
  Form,
} from "@builder.io/qwik-city";
import {
  applyCoupon,
  clearCart,
  getCartState,
  updateCartItemQuantity,
} from "~/lib/cart";

export const useCartLoader = routeLoader$(() => {
  return getCartState();
});

export const useUpdateQuantityAction = routeAction$(
  (data) => {
    return updateCartItemQuantity(Number(data.productId), Number(data.quantity));
  },
  zod$({
    productId: z.coerce.number(),
    quantity: z.coerce.number(),
  }),
);

export const useApplyCouponAction = routeAction$(
  (data) => {
    return applyCoupon(String(data.code ?? "").trim());
  },
  zod$({
    code: z.string(),
  }),
);

export const useClearCartAction = routeAction$(() => {
  return clearCart();
});

export default component$(() => {
  const cartSignal = useCartLoader();
  const updateQuantityAction = useUpdateQuantityAction();
  const applyCouponAction = useApplyCouponAction();
  const clearCartAction = useClearCartAction();

  // Prefer the most recent action result (if any) so the page reflects the
  // latest server-computed state immediately after a form submission,
  // falling back to the loader's data on initial render / navigation.
  const cart =
    clearCartAction.value ??
    applyCouponAction.value ??
    updateQuantityAction.value ??
    cartSignal.value;

  const currency = (n: number) => `$${n.toFixed(2)}`;

  return (
    <div class="cart-page">
      <h1>Shopping Cart</h1>

      {cart.error && (
        <div class="cart-error" role="alert">
          {cart.error}
        </div>
      )}

      {cart.items.length === 0 ? (
        <p class="cart-empty">Your cart is empty.</p>
      ) : (
        <table class="cart-table">
          <thead>
            <tr>
              <th>Product</th>
              <th>Price</th>
              <th>Quantity</th>
              <th>Total</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {cart.items.map((item) => (
              <tr key={item.productId}>
                <td>{item.name}</td>
                <td>{currency(item.price)}</td>
                <td>
                  <Form action={updateQuantityAction} class="inline-form">
                    <input
                      type="hidden"
                      name="productId"
                      value={item.productId}
                    />
                    <input
                      type="number"
                      name="quantity"
                      min={0}
                      value={item.quantity}
                      class="quantity-input"
                    />
                    <button type="submit">Update</button>
                  </Form>
                </td>
                <td>{currency(item.total)}</td>
                <td>
                  <Form action={updateQuantityAction} class="inline-form">
                    <input
                      type="hidden"
                      name="productId"
                      value={item.productId}
                    />
                    <input type="hidden" name="quantity" value={0} />
                    <button type="submit">Remove</button>
                  </Form>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <div class="cart-coupon">
        <h2>Coupon</h2>
        {cart.coupon ? (
          <p class="cart-coupon-active">
            Applied coupon: <strong>{cart.coupon.code}</strong> (
            {cart.coupon.type}
            {cart.coupon.type === "PERCENT" ? ` ${cart.coupon.value}%` : ""}
            {cart.coupon.type === "FIXED"
              ? ` $${cart.coupon.value.toFixed(2)}`
              : ""}
            )
          </p>
        ) : (
          <p>No coupon applied.</p>
        )}

        <Form action={applyCouponAction} class="inline-form">
          <input
            type="text"
            name="code"
            placeholder="Coupon code"
            class="coupon-input"
          />
          <button type="submit">Apply Coupon</button>
        </Form>
      </div>

      <div class="cart-summary">
