export default component$(() => {
  useStylesScoped$(`
    .cart-page {
      max-width: 720px;
      margin: 2rem auto;
      font-family: system-ui, sans-serif;
      padding: 0 1rem;
    }
    .cart-error {
      background: #fdecea;
      color: #b3261e;
      border: 1px solid #f5c6c2;
      padding: 0.75rem 1rem;
      border-radius: 6px;
      margin-bottom: 1rem;
      font-weight: 600;
