    .cart-table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 1.5rem;
    }
    .cart-table th, .cart-table td {
      text-align: left;
      padding: 0.5rem 0.75rem;
      border-bottom: 1px solid #ddd;
    }
    .inline-form {
      display: flex;
      gap: 0.5rem;
      align-items: center;
    }
    .quantity-input {
      width: 4rem;
    }
    .coupon-input {
      width: 12rem;
    }
    .cart-coupon {
      margin-bottom: 1.5rem;
      padding: 1rem;
      background: #f7f7f8;
      border-radius: 8px;
    }
    .cart-coupon-active {
      color: #1a7f37;
      font-weight: 600;
    }
    .cart-summary {
      font-size: 1.05rem;
      margin-bottom: 1.5rem;
    }
    .cart-total {
      font-size: 1.3rem;
      font-weight: 700;
    }
    .clear-cart-btn {
      background: #b3261e;
      color: white;
      border: none;
      padding: 0.5rem 1rem;
      border-radius: 6px;
      cursor: pointer;
    }
    button {
      cursor: pointer;
    }
  `);

  const cartSignal = useCartLoader();
  const updateQuantityAction = useUpdateQuantityAction();
  const applyCouponAction = useApplyCouponAction();
  const clearCartAction = useClearCartAction();

  // Prefer the most recent action result (if any) so the page reflects the
  // latest server-computed state immediately after a form submission,
  // falling back to the loader's data on initial render / navigation.
  const cart =
    clearCartAction.value ??
    applyCouponAction.value ??
    updateQuantityAction.value ??
    cartSignal.value;

  const currency = (n: number) => `$${n.toFixed(2)}`;

  return (
    <div class="cart-page">
      <h1>Shopping Cart</h1>

      {cart.error && (
        <div class="cart-error" role="alert">
          {cart.error}
        </div>
